package org.firstinspires.ftc.teamcode.subsystems;

import com.qualcomm.robotcore.util.ElapsedTime;

import org.firstinspires.ftc.teamcode.config.Tuned;

import java.util.Locale;

// Generated by refract-suite ftc-construct. The turret finds its own zero from its end stops, with no extra hardware
// and wherever it was left (also after being turned while the power was off). Program 3 measured each stop's angle
// from forward (Tuned.yawHomeLeftDeg / yawHomeRightDeg) with this same touch, and the speeds that are safe.
//   1 drive at the nearer stop fast, back off a few degrees, creep in: that angle is the first reference, the zero is
//     set from it and the turret knows where it is
//   2 cross to just short of the other stop (position known now, so fast but with a braking ramp), back off 3 deg
//     and creep in (the same touch as the first stop): the second reference. The two must agree on the span; the zero is their average. Always done when program 3 measured
//     both stops: one stop alone cannot tell a stop from a snag (a cable that catches the turret, a stall mid-travel),
//     and a zero taken on a snag is off by however far the snag is from the stop. The span check catches it and fails
//     loudly instead. With only one stop measured the homing is one-sided and says it is not cross-checked.
// Only after START (R102/G403): a button press starts it, never the INIT loop. The drive, intake and Pinpoint code run
// as usual; the caller keeps aiming and firing off while active().
public final class YawHoming {
    private enum State { IDLE, FIRST, CROSS, SECOND, DONE, FAILED }

    // procedure settings, not robot measurements
    // SECOND_TAIL_S: the braking ramp, the back-off, the creep and the stall wait after the crossing (for the time estimate)
    public static final double SECOND_TAIL_S = 1.2;
    private static final double TOTAL_TIMEOUT_S = 12;
    private static final double SPAN_TOLERANCE_DEG = 0.7, ROUGH_TOLERANCE_DEG = 3.0;
    private static final double CROSS_STOP_SHORT_DEG = 6, CROSS_DONE_DEG = 2.0, TRAVEL_MARGIN_DEG = 30;
    // the crossing moved less than this in CROSS_STALL_S: something holds the turret (a snag, or a first "stop" that was not one)
    private static final double CROSS_STALL_DEG = 0.5, CROSS_STALL_S = 0.4;

    // enough was measured in program 3 to home: the yaw numbers, at least one repeatable stop and the speeds
    public static boolean available() {
        return Yaw.tuned() && Tuned.isSet(Tuned.yawHomeFastDegS, Tuned.yawHomeCreepDegS, Tuned.yawHomeCrossDegS)
                && (Tuned.isSet(Tuned.yawHomeLeftDeg) || Tuned.isSet(Tuned.yawHomeRightDeg));
    }

    private final Yaw yaw;
    private final boolean hintTrusted;
    private final ElapsedTime timer = new ElapsedTime();
    private State state = State.IDLE;
    private StopTouch touch;
    private int firstDir, secondDir;
    private double firstHome, secondHome, firstElapsedS = Double.NaN, firstReferenceDeg;
    private boolean twoSided;
    private String message = "";
    private double doneS = Double.NaN;

    // hintTrusted: the encoder angle is probably still right (the app kept running), so the last degrees before the
    // expected stop are driven slowly
    public YawHoming(Yaw yaw, boolean hintTrusted) {
        this.yaw = yaw;
        this.hintTrusted = hintTrusted;
    }

    public void start() {
        timer.reset();
        boolean left = Tuned.isSet(Tuned.yawHomeLeftDeg), right = Tuned.isSet(Tuned.yawHomeRightDeg);
        double deg = yaw.frontDeg();
        // the stop nearest to where the turret is thought to be (after a power-up the count restarts: about forward)
        boolean firstLeft = left && (!right || (Tuned.yawHomeLeftDeg - deg) <= (deg - Tuned.yawHomeRightDeg));
        firstDir = firstLeft ? 1 : -1;
        firstHome = firstLeft ? Tuned.yawHomeLeftDeg : Tuned.yawHomeRightDeg;
        secondDir = -firstDir;
        secondHome = firstLeft ? Tuned.yawHomeRightDeg : Tuned.yawHomeLeftDeg;
        twoSided = left && right;
        double travel = span() + TRAVEL_MARGIN_DEG;
        touch = StopTouch.fastThenCreep(yaw, firstDir, Tuned.yawHomeFastDegS, Tuned.yawHomeCreepDegS,
                hintTrusted ? firstHome : Double.NaN, travel);
        state = State.FIRST;
    }

    public boolean active() {
        return state == State.FIRST || state == State.CROSS || state == State.SECOND;
    }

    public boolean finished() {
        return state == State.DONE;
    }

    public boolean failed() {
        return state == State.FAILED;
    }

    public String message() {
        return message;
    }

    // seconds the whole homing took (NaN until finished)
    public double doneS() {
        return doneS;
    }

    public String status() {
        switch (state) {
            case FIRST:
                return String.format(Locale.US, "TURRET HOMING %.1f s: finding the %s stop", timer.seconds(), firstDir > 0 ? "left" : "right");
            case CROSS:
                return String.format(Locale.US, "TURRET HOMING %.1f s: crossing to the %s stop", timer.seconds(), secondDir > 0 ? "left" : "right");
            case SECOND:
                return String.format(Locale.US, "TURRET HOMING %.1f s: checking the %s stop", timer.seconds(), secondDir > 0 ? "left" : "right");
            case DONE:
                return String.format(Locale.US, "Turret homed in %.1f s%s", doneS, secondChecked ? String.format(Locale.US, " (both stops, %.2f deg apart from the measured span)", spanOffDeg) : " (one stop only: not cross-checked)");
            case FAILED:
                return "TURRET HOMING FAILED: " + message;
            default:
                return "";
        }
    }

    private boolean secondChecked = false;
    private double spanOffDeg = Double.NaN;
    private double crossProgressDeg = Double.NaN, crossProgressS;

    // every loop while active()
    public void update() {
        if (!active()) return;
        if (timer.seconds() > TOTAL_TIMEOUT_S) {
            fail("took more than " + (int) TOTAL_TIMEOUT_S + " s");
            return;
        }
        switch (state) {
            case FIRST:
                touch.update();
                if (!touch.finished()) return;
                if (touch.failed()) {
                    fail(touch.why());
                    return;
                }
                // a fast hit that did not land on the same stop as the slow touch is not trusted
                if (!Double.isNaN(touch.roughDeg()) && Math.abs(touch.roughDeg() - touch.preciseDeg()) > ROUGH_TOLERANCE_DEG + 1.5) {
                    fail(String.format(Locale.US, "the fast hit and the slow touch differ by %.1f deg", Math.abs(touch.roughDeg() - touch.preciseDeg())));
                    return;
                }
                firstReferenceDeg = touch.preciseDeg();
                yaw.shiftZeroDeg(firstReferenceDeg - firstHome);
                firstElapsedS = timer.seconds();
                if (twoSided) {
                    state = State.CROSS;
                } else {
                    finish();
                }
                break;
            case CROSS: {
                double deg = yaw.frontDeg();
                if (Double.isNaN(crossProgressDeg) || Math.abs(deg - crossProgressDeg) >= CROSS_STALL_DEG) {
                    crossProgressDeg = deg;
                    crossProgressS = timer.seconds();
                } else if (timer.seconds() - crossProgressS >= CROSS_STALL_S) {
                    fail(String.format(Locale.US, "the turret stopped %.0f deg before the other stop: a snag (cable?) or the first stop was not the stop."
                            + " Check the cable, then home again", Math.abs(secondHome - deg)));
                    return;
                }
                double target = secondHome - secondDir * CROSS_STOP_SHORT_DEG;
                double err = target - deg;
                if (Math.abs(err) <= CROSS_DONE_DEG || err * secondDir < 0) {
                    yaw.setRawPower(0);
                    // back off, then creep in: the same touch as the first stop and as program 3's, so both stops read alike
                    // (taking the turret where the crossing left it read up to 2 deg into the stop, so the zero depended on
                    // which stop came last)
                    touch = StopTouch.backoffThenCreep(yaw, secondDir, deg, StopTouch.BACKOFF_DEG, Tuned.yawHomeCreepDegS,
                            CROSS_STOP_SHORT_DEG + StopTouch.BACKOFF_DEG + TRAVEL_MARGIN_DEG);
                    state = State.SECOND;
                    break;
                }
                StopTouch.driveRate(yaw, StopTouch.crossRate(deg, target, secondHome, secondDir, Tuned.yawHomeCrossDegS));
                break;
            }
            case SECOND: {
                touch.update();
                if (!touch.finished()) return;
                if (touch.failed()) {
                    fail("second stop: " + touch.why());
                    return;
                }
                double off = touch.preciseDeg() - secondHome;
                if (Math.abs(off) > SPAN_TOLERANCE_DEG) {
                    fail(String.format(Locale.US, "the two stops are %.1f deg off the measured span: one of the touches was false", off));
                    return;
                }
                // average the two references: each is off by half of the disagreement, one each way
                yaw.shiftZeroDeg(off / 2);
                spanOffDeg = off;
                secondChecked = true;
                finish();
                break;
            }
            default:
                break;
        }
    }

    // STOP, or the caller gave up
    public void abort() {
        if (active()) {
            yaw.setRawPower(0);
            state = State.IDLE;
        }
    }

    private void finish() {
        yaw.setRawPower(0);
        yaw.homed();
        doneS = timer.seconds();
        state = State.DONE;
    }

    private void fail(String why) {
        yaw.setRawPower(0);
        message = why;
        state = State.FAILED;
    }

    // projected time of the crossing and the second touch
    public static double secondSideS(double span, double crossDegS) {
        return (span - 2 * CROSS_STOP_SHORT_DEG) / crossDegS + SECOND_TAIL_S;
    }

    private double secondSideS() {
        return secondSideS(span(), Tuned.yawHomeCrossDegS);
    }

    // the whole travel between the two stops (or an estimate from the soft limits when only one stop passed)
    private double span() {
        if (twoSided) return Tuned.yawHomeLeftDeg - Tuned.yawHomeRightDeg;
        return (Tuned.yawMaxDeg - Tuned.yawMinDeg) + 2 * 10;
    }
}
